style.css:
@-moz-document domain("youtube.com") {
/* =========================================================
       1. BACKGROUND & LAYERS (GIF Visibility Fixed)
       ========================================================= */
    html, body, ytd-app, #background, ytd-watch-flexy, ytd-browse, #columns {
        background: transparent !important;
    }

    body::before {
        content: "";
        position: fixed;
        top: 0; left: 0;
        width: 100vw; height: 100vh;
        z-index: -1;
        background-image: url('https://media1.tenor.com/m/uvC1Vj7ooUUAAAAC/cat-not-mine.gif') !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        /* Brightened the GIF so it's clearly visible */
        filter: blur(6px) brightness(0.8) saturate(1.2) !important; 
        transform: scale(1.1); 
    }

    /* Lighter dark overlay so the GIF shines through */
    #page-manager, ytd-masthead {
        background: rgba(10, 5, 20, 0.4) !important; 
        backdrop-filter: blur(3px) !important;
    }

    /* =========================================================
       2. LO-FI NEON LOGO
       ========================================================= */
    #logo-icon svg, #logo-icon-container svg {
        display: block !important; 
        filter: drop-shadow(0px 0px 8px #ff007f) hue-rotate(280deg) brightness(1.2) !important;
    }
    #logo-icon-container::after { display: none !important; }

    /* =========================================================
       3. BUTTONS & CHIPS (Restored Squircle & Glass Design)
       ========================================================= */
    @keyframes floaty {
        0% { transform: translateY(0px); }
        50% { transform: translateY(-4px); }
        100% { transform: translateY(0px); }
    }

    button, a.ytd-button-renderer, tp-yt-paper-button, .ytp-button,
    yt-chip-cloud-chip-renderer, ytd-mini-guide-entry-renderer, ytd-guide-entry-renderer {
        background-color: rgba(30, 20, 40, 0.6) !important; 
        border: 1px solid rgba(255, 113, 206, 0.3) !important;
        border-radius: 18px 6px 18px 6px !important; 
        color: #fdf0f5 !important;
        transition: all 0.3s ease !important;
        backdrop-filter: blur(5px) !important;
        margin: 2px !important;
    }

    ytd-mini-guide-entry-renderer yt-icon, ytd-guide-entry-renderer yt-icon {
        color: #fdf0f5 !important;
    }

    yt-chip-cloud-chip-renderer[selected] {
        background-color: rgba(255, 113, 206, 0.5) !important;
        border-color: #ffe259 !important;
        box-shadow: 0 0 10px rgba(255, 113, 206, 0.6) !important;
        color: #fff !important;
    }

    button:hover, a.ytd-button-renderer:hover, tp-yt-paper-button:hover, .ytp-button:hover,
    yt-chip-cloud-chip-renderer:hover, ytd-mini-guide-entry-renderer:hover, ytd-guide-entry-renderer:hover {
        background-color: rgba(255, 113, 206, 0.3) !important;
        border-color: #ffe259 !important;
        box-shadow: 0 0 15px rgba(255, 113, 206, 0.4), inset 0 0 10px rgba(255, 113, 206, 0.2) !important;
        animation: floaty 2s ease-in-out infinite !important;
        cursor: pointer !important;
    }

    /* =========================================================
       4. VIDEO PLAYER SEEKBAR (Restored Gradient & Glowing Ball)
       ========================================================= */
    .ytp-swatch-background-color, .ytp-play-progress {
        background: linear-gradient(90deg, #ff7b00 0%, #ff007f 100%) !important; 
    }

    .ytp-scrubber-button {
        background-color: #ffe259 !important; 
        border-radius: 50% !important;
        box-shadow: 0 0 15px #ffe259, 0 0 25px #ff7b00 !important;
        transform: scale(1.4) !important; 
        border: 2px solid #fff !important;
    }

    .ytp-scrubber-button:hover {
        box-shadow: 0 0 20px #ffe259, 0 0 30px #ff7b00 !important;
    }

    /* =========================================================
       5. TEXT SHADOW FOR READABILITY
       ========================================================= */
    yt-formatted-string, span, div, h1, h3 {
        text-shadow: 0 1px 4px rgba(0,0,0, 0.9) !important;
    }
}
